+
+async function workItemExistsOnMain(
+  mainSql: Sql,
+  id: string
+): Promise<boolean> {
+  const rows = await mainSql.unsafe(
+    `SELECT 1 FROM work_items WHERE id = ${escapeValue(id)} LIMIT 1`
+  );
+  return rows.length > 0;
