+
+async function resolveCitationEndpoint(
+  branchConn: ReservedSql,
+  mainSql: Sql,
+  id: string
+): Promise<CitationEndpoint | null> {
+  if (isWorkItemEndpointId(id)) {
+    return (await workItemExistsOnMain(mainSql, id))
+      ? { kind: "work", onBranch: false }
+      : null;
