+
+describe("CONFIDENCE_NOT_AUTHOR_SET — confidence is not a caller input", () => {
+  it("drops confidencePct from a knowledge entry input (no write surface accepts it)", () => {
+    const parsed = KnowledgeEntryInputSchema.parse({
